insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('87c1f7ca-8c82-4639-9a79-a09c987d1dcb', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$inleiding: Safetybell heeft een patent op videodeurbellen en streeft naar maximale winst$$,
   $$economie-vwo-2025-ii-safetybell-context1.png$$,
   $$Het bedrijf Safetybell heeft een patent op de productie (en verkoop) van video-deurbellen. Deze deurbellen hebben een videocamera en een ingebouwd alarm, wat bijdraagt aan een gevoel van veiligheid. Safetybell streeft naar maximale winst.$$, 'inline'),
  ('517d36b0-84f7-446b-9198-add326e1f2bf', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$tabel 1: financiële gegevens Safetybell$$,
   $$economie-vwo-2025-ii-safetybell-context2.png$$,
   $$Tabel 1 Financiële gegevens Safetybell
prijsafzetfunctie | GO = −50Q + 400
gemiddelde variabele kosten (in €) | GVK = 12,5Q + 100
totale constante kosten (in €) | TCK = 600.000
P (=GO) | verkoopprijs in €
Q | afzet in tienduizenden stuks.$$, 'inline'),
  ('89669db7-65dd-4837-bd2a-457d4559682e', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$figuur 1: marktsituatie van Safetybell$$,
   $$economie-vwo-2025-ii-safetybell-context3.png$$,
   $$Figuur 1 Marktsituatie van Safetybell
verticale as: in €; horizontale as: Q (x 10.000), 0 tot 9.
GO: dalende lijn van 400 bij Q = 0 naar 0 bij Q = 8.
MO: dalende lijn van 400 bij Q = 0 naar 0 bij Q = 4.
MK: stijgende lijn van 100 bij Q = 0 naar 300 bij Q = 8.$$, 'inline'),
  ('df7f660f-c991-4b58-bc81-459a53315330', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$overheid overweegt subsidie per videodeurbel aan de laagste inkomensgroepen$$,
   $$economie-vwo-2025-ii-safetybell-context4.png$$,
   $$De overheid vindt dat de videodeurbellen zorgen voor een betere veiligheid en dat daardoor de maatschappelijke kosten als gevolg van criminaliteit dalen. De overheid overweegt een subsidie te geven per videodeurbel aan de laagste inkomensgroepen.$$, 'inline'),
  ('6aba0612-714b-4a36-bd6b-2613f06facd0', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$subsidie van € 50 per videodeurbel aan alle consumenten$$,
   $$economie-vwo-2025-ii-safetybell-context5.png$$,
   $$Stel dat de overheid een subsidie van € 50 per videodeurbel geeft aan alle consumenten. Hierdoor verschuift de GO- en MO-lijn.$$, 'inline'),
  ('47206bc2-7036-4454-bed1-6a776851a5f2', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$subsidie aan de producent is eenvoudiger uit te voeren$$,
   $$economie-vwo-2025-ii-safetybell-context6.png$$,
   $$In de praktijk blijkt dat het verstrekken van een subsidie van € 50 per videodeurbel aan de producent eenvoudiger is uit te voeren dan aan de consument. Daarmee ontstaat de marktsituatie zoals getoond in figuur 2.$$, 'inline'),
  ('87d7baf6-75f5-4430-bdf4-8fbaba0fbf60', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$figuur 2: marktsituatie na subsidie aan de producent (MK’)$$,
   $$economie-vwo-2025-ii-safetybell-context7.png$$,
   $$Figuur 2 Marktsituatie van Safetybell na subsidie aan de producent
verticale as: in €; horizontale as: Q (x 10.000), 0 tot 9.
GO: dalende lijn van 400 bij Q = 0 naar 0 bij Q = 8.
MO: dalende lijn van 400 bij Q = 0 naar 0 bij Q = 4.
MK: stijgende lijn van 100 bij Q = 0 naar 300 bij Q = 8.
MK’: stijgende lijn evenwijdig aan MK, van 50 bij Q = 0 naar 250 bij Q = 8.$$, 'inline'),
  ('454a8792-9f61-4301-9fb4-cad03cc83edd', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$verschuiving MK naar MK’ door subsidie; maximale totale winst$$,
   $$economie-vwo-2025-ii-safetybell-context8.png$$,
   $$De verschuiving van de MK-lijn naar MK’-lijn is het gevolg van de subsidie aan de producent. Safetybell blijft streven naar maximale totale winst.$$, 'inline'),
  ('d5d46975-85a3-45e0-b6cc-53a349d52159', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$patent verloopt; marktevenwicht bij volledige mededinging$$,
   $$economie-vwo-2025-ii-safetybell-context9.png$$,
   $$Na tien jaar verloopt het patent op de videodeurbellen. Uiteindelijk ontstaat een marktevenwicht bij volledige mededinging.$$, 'inline'),
  ('7bb10d69-7d6d-408e-bdc6-86e3fabd7a99', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$uitwerkbijlage vraag 4: figuur 1$$,
   $$economie-vwo-2025-ii-safetybell-context10.png$$,
   $$uitwerkbijlage vraag 4
Figuur 1 (kopie van figuur 1 met GO, MO en MK)$$, 'uitwerkbijlage'),
  ('45744203-4734-4abd-903f-18c096a4c793', '3596d5bd-913a-481a-ad43-510b31abb7d4', $$uitwerkbijlage vraag 5: figuur 2$$,
   $$economie-vwo-2025-ii-safetybell-context11.png$$,
   $$uitwerkbijlage vraag 5
Figuur 2 (kopie van figuur 2 met GO, MO, MK en MK’)$$, 'uitwerkbijlage'),
  ('80574145-47a5-416d-b294-1adafd3ec170', '0fb8dc8d-a37d-4e2b-b7d5-d515065dcbb4', $$inleiding: model van een econoom voor het pensioenstelsel (komende 20 jaar)$$,
   $$economie-vwo-2025-ii-pensioenmodel-context1.png$$,
   $$Een econoom heeft de verwachtingen over het pensioenstelsel uitgewerkt in een model voor de komende 20 jaar (figuur 1).$$, 'inline'),
  ('f413a96d-34de-4035-a7ea-acaf0bcae5b3', '0fb8dc8d-a37d-4e2b-b7d5-d515065dcbb4', $$figuur 1: pensioenmodel econoom 2024–2044$$,
   $$economie-vwo-2025-ii-pensioenmodel-context2.png$$,
   $$Figuur 1 Pensioenmodel econoom (2024–2044)
linkeras: premies in % van pensioenvermogen (1,5 tot 3,1); rechteras: pensioenvermogen als % van bbp (150 tot 270+).
Staven (pensioenvermogen, rechteras) stijgen van ongeveer 220 in 2024 tot ongeveer 280 in 2044.
Lijn (premies, linkeras) daalt van ongeveer 2,25 in 2024 tot ongeveer 1,75 in 2044.
Legenda: lijn = premies (linkeras); staven = pensioenvermogen (rechteras).$$, 'inline'),
  ('44a2c6bc-6ccd-400a-890b-13ac434aada3', '0fb8dc8d-a37d-4e2b-b7d5-d515065dcbb4', $$aannames a t/m f over de periode 2025–2044$$,
   $$economie-vwo-2025-ii-pensioenmodel-context3.png$$,
   $$Bij het opstellen van het model is de econoom uitgegaan van onderstaande aannames over de periode 2025−2044: a jaarlijkse inflatie = 2%; b jaarlijkse reële economische groei = 0,5%; c jaarlijkse rendement pensioenvermogen = 3,5%; d de premiedruk (premie als % van het bbp) blijft gelijk; e het aantal premieplichtingen (actieven) blijft gelijk; f de kapitaalinkomens blijven gelijk.$$, 'inline'),
  ('939bdadd-192c-4d18-8463-d27f4113126b', '0fb8dc8d-a37d-4e2b-b7d5-d515065dcbb4', $$netto opgebouwde pensioenbesparing$$,
   $$economie-vwo-2025-ii-pensioenmodel-context4.png$$,
   $$Pensioenfondsen noemen het verschil tussen de betaalde premies en uitgekeerde pensioenen de netto opgebouwde pensioenbesparing.$$, 'inline'),
  ('28175bb4-e18b-4887-9d9f-8aa8b5b80ef0', '0fb8dc8d-a37d-4e2b-b7d5-d515065dcbb4', $$lijn in figuur 1: premies als % van het pensioenvermogen dalen$$,
   $$economie-vwo-2025-ii-pensioenmodel-context5.png$$,
   $$De lijn in figuur 1 geeft aan dat de premies als percentage van het totale pensioenvermogen dalen.$$, 'inline'),
  ('ad13c60e-0b3f-4384-bc89-46cb1aa35e31', '0fb8dc8d-a37d-4e2b-b7d5-d515065dcbb4', $$hogere pensioenleeftijd kan koopkracht huidige premieplichtigen verhogen$$,
   $$economie-vwo-2025-ii-pensioenmodel-context6.png$$,
   $$De econoom heeft geen rekening gehouden met de pensioenleeftijd. De econoom geeft aan dat het verhogen van de pensioenleeftijd kan leiden tot een hogere koopkracht van de huidige premieplichtigen.$$, 'inline'),
  ('48b68de0-2730-40e2-a9a1-5460e812b636', '028f96a1-7de0-442b-a5bc-507d7fcee9bf', $$inleiding: arbeidsmigranten in de EU maken geld over naar het land van herkomst$$,
   $$economie-vwo-2025-ii-hulplijn-context1.png$$,
   $$Arbeidsmigranten in de Europese Unie (EU) sturen vaak maandelijks een deel van hun inkomen naar hun gezinnen in het land van herkomst (bijvoorbeeld naar een Afrikaans land) om hen te onderhouden of onderwijs te financieren. Als het land van herkomst in een laagconjunctuur belandt, zullen migranten in de EU een groter bedrag overmaken.$$, 'inline'),
  ('f313cdeb-61d9-4bd1-bf49-0791e0e88320', '028f96a1-7de0-442b-a5bc-507d7fcee9bf', $$geld-overmaak-bedrijf (GOB): commissie en lagere wisselkoers$$,
   $$economie-vwo-2025-ii-hulplijn-context2.png$$,
   $$De migranten versturen geld via een geld-overmaak-bedrijf (GOB). Het GOB rekent een commissie (=vergoeding) per transactie en hanteert een lagere wisselkoers dan de officiële wisselkoers op de valutamarkt. De gezinnen kunnen het geld contant ophalen bij een vestiging van het GOB.$$, 'inline'),
  ('5bf2d9a5-5c73-478f-9781-c90e6774408b', '028f96a1-7de0-442b-a5bc-507d7fcee9bf', $$migrant maakt € 500 over; commissie € 7; wisselkoersen 10,36 en 10,81 frank$$,
   $$economie-vwo-2025-ii-hulplijn-context3.png$$,
   $$Een migrant in de EU maakt € 500 over naar de familie in een Afrikaans land. Het GOB rekent eerst een commissie van € 7, en hanteert daarna een wisselkoers van € 1 = 10,36 frank. De officiële wisselkoers is € 1 = 10,81 frank. Het verschil tussen de wisselkoersen plus de commissie vormt de winst van het GOB.$$, 'inline'),
  ('df3cd715-e628-48fb-a2c5-22fb21bedc75', '028f96a1-7de0-442b-a5bc-507d7fcee9bf', $$figuur 1: schema transactie via het GOB$$,
   $$economie-vwo-2025-ii-hulplijn-context4.png$$,
   $$Figuur 1 Schema transactie via het GOB
Europa → (€ 500 overdracht) → GOB (€ 7 commissie) → (wisselkoers) → Afrika$$, 'inline'),
  ('6bedd6c8-1b74-4729-bb9a-55fe9eb41d88', '028f96a1-7de0-442b-a5bc-507d7fcee9bf', $$economen onderzoeken een Afrikaans land met vaste wisselkoers$$,
   $$economie-vwo-2025-ii-hulplijn-context5.png$$,
   $$Economen onderzoeken de economie van een specifiek Afrikaans land. Ze gebruiken tabel 1 en laten de financiële rekening van de betalingsbalans buiten beschouwing. Het land hanteert een vaste (officiële) wisselkoers met de euro.$$, 'inline'),
  ('6b35dfe5-e205-4066-9bba-1cf38a7b67b5', '028f96a1-7de0-442b-a5bc-507d7fcee9bf', $$tabel 1: macro-economische gegevens van het Afrikaanse land$$,
   $$economie-vwo-2025-ii-hulplijn-context6.png$$,
   $$Tabel 1 Macro-economische gegevens van het Afrikaanse land
| 2019 | 2020 | 2021
bbp (in miljarden frank) | 103,3 | 109,7 | 117,9
begrotingssaldo (% van bbp) | -4,5 | -3,5 | -3,7
saldo lopende rekening (% van bbp) | -4 | -3,4 | -3,4
ontvangen inkomensoverdrachten (in miljarden frank) | 6,70 | 6,82 | 6,92$$, 'inline'),
  ('16b1bfda-84f7-4a9a-815b-6268bffa5b2f', '028f96a1-7de0-442b-a5bc-507d7fcee9bf', $$saldo lopende rekening verslechtert na 2021$$,
   $$economie-vwo-2025-ii-hulplijn-context7.png$$,
   $$De economen verwachten dat het saldo op de lopende rekening na 2021 zal verslechteren.$$, 'inline'),
  ('5d6c634d-8ee3-4cb0-9279-c53e3a16a16a', '8a8f1355-7bfc-4718-be88-326ba230ed1c', $$inleiding: overheid financiert scholen met een lumpsum per leerling$$,
   $$economie-vwo-2025-ii-strijd-om-de-leerling-context1.png$$,
   $$De overheid investeert in de ontwikkeling van menselijk kapitaal bij haar bevolking door onderwijs te financieren. Middelbare scholen ontvangen elk jaar een bepaald bedrag dat ze aan personeel en het onderhoud van het gebouw mogen besteden. Deze financiering heet de lumpsum en is een vast bedrag per leerling.$$, 'inline'),
  ('23209a97-0f75-4ae1-821b-a8f82329acd7', '8a8f1355-7bfc-4718-be88-326ba230ed1c', $$scholen besteden lumpsum aan marketing; inspectie controleert alleen kwaliteit$$,
   $$economie-vwo-2025-ii-strijd-om-de-leerling-context2.png$$,
   $$Scholen streven naar een zo hoog mogelijk aantal leerlingen en besteden daarom een groot deel van de lumpsum aan marketing. De Inspectie van het Onderwijs is uitsluitend gericht op het controleren van de kwaliteit van het geboden onderwijs.$$, 'inline'),
  ('7012b83d-578a-4da1-8b61-ef07be452150', '8a8f1355-7bfc-4718-be88-326ba230ed1c', $$model met twee scholen: Rij-college en Kolom-college$$,
   $$economie-vwo-2025-ii-strijd-om-de-leerling-context3.png$$,
   $$Een econoom maakt een model om de gevolgen van het marketingbeleid aan te tonen (zie bron 1 en matrix 1). In het model zijn er twee scholen: het Rij-college en het Kolom-college. Zij ervaren uitsluitend concurrentie van elkaar.$$, 'inline'),
  ('93d0e731-9449-4eaa-bfd8-e58029095d61', '8a8f1355-7bfc-4718-be88-326ba230ed1c', $$bron 1: gegevens en aannames model$$,
   $$economie-vwo-2025-ii-strijd-om-de-leerling-context4.png$$,
   $$Bron 1 Gegevens en aannames model
Onderstaande gegevens gelden voor het vorige schooljaar en het huidige schooljaar.
− De afzetfuncties zijn gelijk aan:
qVrij = 800 + 2Mrij – 0,5Mkolom
qVkolom = 800 + 2Mkolom – 0,5Mrij
− qv = het aantal leerlingen per school
− M = het percentage van het maximale marketingbudget (M = 100 als een school het volledige marketingbudget inzet)
− De school ontvangt een lumpsum van € 6.000 per leerling per jaar.
− Het maximale budget voor marketing bestaat uit 10% van de lumpsum van het vorige schooljaar. Marketingkosten zijn constante kosten.
− De kostenfunctie voor elke school luidt: TK = 3.000q + 2.510.000 + marketingkosten (q = aantal leerlingen)$$, 'inline'),
  ('03ef6ef0-5ab8-4391-a390-38128a72eddf', '8a8f1355-7bfc-4718-be88-326ba230ed1c', $$matrix 1: verandering financiële reserve bij inzet marketing, met noot$$,
   $$economie-vwo-2025-ii-strijd-om-de-leerling-context5.png$$,
   $$Matrix 1 Verandering financiële reserve (x € 1.000) bij inzet marketing
(eerste getal: Rij-college; tweede getal, cursief: Kolom-college)
| Kolom-college M = 0% | M = 50% | M = 100%
Rij-college M = 0% | -110 ; -110 (A)¹⁾ | -185 ; -50 (B) | -260 ; 10 (C)
Rij-college M = 50% | -50 ; -185 (D) | -125 ; -125 (E) | -200 ; -65 (F)
Rij-college M = 100% | 10 ; -260 (G) | -65 ; -200 (H) | -140 ; -140 (I)
noot 1: In het vorige schooljaar is de financiële reserve van beide scholen met € 110.000 afgenomen.$$, 'inline'),
  ('9961af81-edae-4e2b-acdb-5fbb42399f9c', '8a8f1355-7bfc-4718-be88-326ba230ed1c', $$vorig schooljaar voerden beide scholen geen marketing (cel A)$$,
   $$economie-vwo-2025-ii-strijd-om-de-leerling-context6.png$$,
   $$In het vorige schooljaar voerden beide scholen geen marketing (cel A).$$, 'inline'),
  ('9264874e-72d7-4954-a872-aa22d9ababb6', '8a8f1355-7bfc-4718-be88-326ba230ed1c', $$fusie tot één school met 1.600 leerlingen zonder marketingkosten$$,
   $$economie-vwo-2025-ii-strijd-om-de-leerling-context7.png$$,
   $$De scholen besluiten te fuseren tot één school met 1.600 leerlingen. De school zal dan geen marketingkosten hebben. De totale constante kosten moeten afnemen om break-even te draaien.$$, 'inline'),
  ('14ba0a72-fefb-4cda-8fc0-44470e09141e', 'bd5896ce-3336-4ba0-9257-02ace78c1f6a', $$inleiding: voorstellen versoepeling ontslagrecht en kortere opzegtermijn$$,
   $$economie-vwo-2025-ii-soepeler-context1.png$$,
   $$Een regeringspartij doet twee voorstellen om de arbeidsmarkt te flexibiliseren:
− Het ontslagrecht moet worden versoepeld (= voor werkgevers moet het makkelijker worden om werknemers te ontslaan).
− De opzegtermijn moet korter worden (= de periode dat een werknemer met een vast contract verplicht moet doorwerken na ontslag door de werknemer / werkgever).$$, 'inline'),
  ('a19b9f64-fe88-4e3f-be48-d4944203ad72', 'bd5896ce-3336-4ba0-9257-02ace78c1f6a', $$kortere opzegtermijn vergroot het berovingsprobleem$$,
   $$economie-vwo-2025-ii-soepeler-context2.png$$,
   $$De verkorting van de opzegtermijn kan ertoe leiden dat het berovingsprobleem in arbeidsrelaties groter wordt, waardoor de loonkosten per product kunnen toenemen.$$, 'inline'),
  ('84f8d753-7cca-440b-97da-2bb2aa3da3f5', 'bd5896ce-3336-4ba0-9257-02ace78c1f6a', $$econoom gebruikt het IS-MB-GA-model; negatieve vraagschok$$,
   $$economie-vwo-2025-ii-soepeler-context3.png$$,
   $$Om de macro-economische effecten van beide voorstellen te onderzoeken, gebruikt een econoom het IS-MB-GA model. Figuren 1 en 2 tonen een negatieve vraagschok waardoor de productie kleiner is dan het productiepotentieel. Figuur 1 toont een model met een starre arbeidsmarkt en figuur 2 toont een model met een flexibele arbeidsmarkt.$$, 'inline'),
  ('49888425-5107-4095-8f25-c254e8aab2d8', 'bd5896ce-3336-4ba0-9257-02ace78c1f6a', $$figuur 1 (starre arbeidsmarkt) en figuur 2 (flexibele arbeidsmarkt) met legenda$$,
   $$economie-vwo-2025-ii-soepeler-context4.png$$,
   $$Figuur 1 Starre arbeidsmarkt | Figuur 2 Flexibele arbeidsmarkt
Beide figuren: boven een IS-MB-diagram (r tegen Y) met horizontale MB-lijn en een verschuiving van IS₀ naar IS₁ (naar links); onder een diagram met π tegen Y en de GA₀-curve.
Figuur 1: GA₀ loopt vlak (licht stijgend).
Figuur 2: GA₀ loopt steil.
r = reële rente in procenten
π = inflatie in procenten
Y = reële productie / inkomen$$, 'inline'),
  ('297b46b4-b3d2-40de-a79a-d6356c210013', 'b718262f-594b-4fa9-9290-2ac3adbc5431', $$inleiding: watertekorten in droge zomers leiden tot overconsumptie$$,
   $$economie-vwo-2025-ii-drinkwater-context1.png$$,
   $$In lange, droge zomers ontstaan er geregeld watertekorten. De vraag naar (drink)water is dan veel groter dan het aanbod, waardoor overconsumptie ontstaat. Overconsumptie ontstaat als de gevraagde hoeveelheid boven de capaciteit komt, waardoor de reserves opraken.$$, 'inline'),
  ('3e0db238-2de3-4e77-a7ab-658fea8d7bc2', 'b718262f-594b-4fa9-9290-2ac3adbc5431', $$doelen overheid: overconsumptie tegengaan, totale kosten niet laten stijgen$$,
   $$economie-vwo-2025-ii-drinkwater-context2.png$$,
   $$De overheid stelt zich de volgende doelen:
1 Overconsumptie van drinkwater (in de zomer) tegengaan.
2 De totale kosten (van de waterrekening) voor een gemiddeld huishouden mogen niet stijgen ten opzichte van de situatie vóór de droogte.$$, 'inline'),
  ('ee60060b-4593-479b-9979-4dbf718476fa', 'b718262f-594b-4fa9-9290-2ac3adbc5431', $$prijs € 1 per 1.000 liter; model met heffing van € 1 per 1.000 liter$$,
   $$economie-vwo-2025-ii-drinkwater-context3.png$$,
   $$In de situatie vóór de droogte was de prijs van water € 1 per 1.000 liter. Een econoom stelt een model op waarin een heffing van € 1 per 1.000 liter water wordt ingevoerd (zie figuur 1).$$, 'inline'),
  ('a13e3e35-0883-4cd7-ab1f-96a6cb294f22', 'b718262f-594b-4fa9-9290-2ac3adbc5431', $$figuur 1: vraag en aanbod van drinkwater per maand, met legenda$$,
   $$economie-vwo-2025-ii-drinkwater-context4.png$$,
   $$Figuur 1 Vraag en aanbod van drinkwater per maand
verticale as: prijs; horizontale as: Q (in 1.000 liter).
Horizontale aanbodlijnen Qₐ₁ bij P = € 1 en Qₐ₂ bij Ph = € 2.
Dalende vraaglijnen Qᵥ₁ en Qᵥ₂ (rechts van Qᵥ₁).
Qᵥ₁ snijdt Qₐ₂ bij Q = 11, Qₐ₁ bij Q = 12 en de Q-as bij 13.
Qᵥ₂ snijdt Qₐ₂ bij Q = 14 (Q’), Qₐ₁ bij Q = 15 en de Q-as bij 16.
Qₐ₁ = aanbodlijn voor heffing; Qₐ₂ = aanbodlijn na heffing
Qᵥ₁ = vraaglijn september t/m juni
Qᵥ₂ = vraaglijn in droogste maanden juli en augustus
Q’ = maandelijkse productiecapaciteit bij droogte
P = prijs voor heffing in euro’s; Ph = prijs na heffing in euro’s$$, 'inline'),
  ('7311587e-3e57-4c25-a94c-ae08f9914f7b', 'b718262f-594b-4fa9-9290-2ac3adbc5431', $$tweede model: gepersonaliseerd schijvenstelsel op drinkwater$$,
